script:
frappe.ui.form.on('Sales Invoice', {
    refresh(frm) {
        // Show FBR status indicator
        if (frm.doc.custom_fbr_status) {
            const status = frm.doc.custom_fbr_status;
            const indicator = status === 'Valid' ? 'green' : status === 'Invalid' ? 'red' : 'orange';
            frm.dashboard.add_indicator(__('FBR Status: {0}', [status]), indicator);
        }

        if (frm.doc.docstatus === 1) {
            frm.add_custom_button(__('Post to FBR'), async () => {
                await queue_sales_invoice_to_fbr(frm);
            });
        }

        if (frm.doc.docstatus === 0 || frm.doc.docstatus === 1) {
            frm.add_custom_button(__('Show FBR Payload'), async () => {
                try {
                    const r = await frappe.call({
                        method: 'fbr_e_invoicing.api.build_fbr_payload.build_fbr_payload',
                        args: { sales_invoice_name: frm.doc.name },
                        freeze: true,
                        freeze_message: __('Building payload...')
                    });

                    if (r && r.message) {
                        const json = JSON.stringify(r.message.payload || r.message, null, 2);
                        const d = new frappe.ui.Dialog({
                            title: __('FBR Payload'),
                            size: 'large',
                            fields: [
                                {
                                    fieldtype: 'Code',
                                    fieldname: 'payload',
                                    options: 'JSON',
                                    read_only: 1,
                                    label: __('Payload'),
                                    height: 420
                                }
                            ],
                            primary_action_label: __('Copy to Clipboard'),
                            primary_action: () => {
                                const val = d.get_value('payload');
                                frappe.utils.copy_to_clipboard(val);
                                frappe.show_alert({ message: __('Copied!'), indicator: 'green' });
                            }
                        });
                        d.set_value('payload', json);
                        d.show();
                    }
                } catch (err) {
                    frappe.msgprint({
                        title: __('Error'),
                        indicator: 'red',
                        message: __(err?.message || 'Failed to build payload')
                    });
                }
            });
        }
    }
});

// Function to queue invoice FBR posting
async function queue_sales_invoice_to_fbr(frm) {
    try {
        const r = await frappe.call({
            method: 'fbr_e_invoicing.api.fbr_queue.add_to_queue',
            args: {
                doctype: 'Sales Invoice',
                docname: frm.doc.name,
                status: 'Pending'
            },
            freeze: true,
            freeze_message: __('Queuing invoice to FBR...')
        });

        const response = r && r.message;
        if (!response) {
            frappe.show_alert({
                message: __('No response received from FBR system.'),
                indicator: 'orange'
            });
            return;
        }

        if (response.success) {
            let message = __('Invoice queued for FBR submission successfully.');
            if (response.state === 'already_queued') message = __('Invoice is already queued for FBR submission.');
            else if (response.state === 'already_processing') message = __('Invoice is currently being processed by FBR.');

            frappe.show_alert({ message, indicator: 'green' });
            // Optionally kickstart the background worker for fast UX
            frappe.call({ method: 'fbr_e_invoicing.api.fbr_queue.process_queue' });

        } else {
             frappe.msgprint({
                title: __('Error'),
                indicator: 'red',
                message: __(response.error || 'Failed to queue invoice.')
            });
        }
    } catch (err) {
        frappe.msgprint({
            title: __('Error'),
            indicator: 'red',
            message: __(err?.message || 'Failed to queue invoice.')
        });
    }
}

frappe.ui.form.on('POS Invoice', {
    refresh(frm) {
        // Show FBR status indicator
        if (frm.doc.custom_fbr_status) {
            const status = frm.doc.custom_fbr_status;
            const indicator = status === 'Valid' ? 'green' : status === 'Invalid' ? 'red' : 'orange';
            frm.dashboard.add_indicator(__('FBR Status: {0}', [status]), indicator);
        }

        if (frm.doc.docstatus === 0 || frm.doc.docstatus === 1) {
            // Show FBR Payload
            frm.add_custom_button(__('Show FBR Payload'), async () => {
                await show_pos_fbr_payload_dialog(frm);
            });
        }
    }
});

// Function to show FBR payload dialog
async function show_pos_fbr_payload_dialog(frm) {
    try {
        const r = await frappe.call({
            method: 'fbr_e_invoicing.api.build_fbr_payload.build_pos_fbr_payload',
            args: { pos_invoice_name: frm.doc.name },
            freeze: true,
            freeze_message: __('Building payload...')
        });

        if (r && r.message) {
            const json = JSON.stringify(r.message.payload || r.message, null, 2);
            const d = new frappe.ui.Dialog({
                title: __('FBR Payload'),
                size: 'large',
                fields: [
                    {
                        fieldtype: 'Code',
                        fieldname: 'payload',
                        options: 'JSON',
                        read_only: 1,
                        label: __('Payload'),
                        height: 420
                    }
                ],
                primary_action_label: __('Copy to Clipboard'),
                primary_action: () => {
                    const val = d.get_value('payload');
                    frappe.utils.copy_to_clipboard(val);
                    frappe.show_alert({ message: __('Copied!'), indicator: 'green' });
                }
            });
            d.set_value('payload', json);
            d.show();
        }
    } catch (err) {
        frappe.msgprint({
            title: __('Error'),
            indicator: 'red',
            message: __(err?.message || 'Failed to build payload')
        });
    }
}
